    private int head, tail, size;
    public ArrayQueue(int n) { data = new Object[n]; }
    public void enqueue(T item) {
        if (size == data.length) throw new IllegalStateException("Queue full");
        data[tail] = item;
        tail = (tail + 1) % data.length;
        size++;
    }
